ST.xhtml:
// Вызов основной программы
PRG_System();
// >>> BULK_SYNC_ANCHOR: PRG_PLC_A <<<

// Вызов основной программы
PRG_System();
// >>> BULK_SYNC_ANCHOR: PRG_PLC_B <<<

// 0. Обновление системного времени
GVL_Vars.G_System_Time_MS := GVL_Vars.G_System_Time_MS + 10; 

// 1. Логика резервирования (ТЗ 11.1)
fbHeartbeat(
    VI_Local_ID := GVL_Vars.G_Local_PLC_ID,
    VI_System_Time := GVL_Vars.G_System_Time_MS,
    VI_Remote_Pulse := GVL_Vars.G_Remote_PLC_Pulse,
    VO_Is_Active => L_Is_Active
);
GVL_Vars.G_Active_PLC_ID := SEL(L_Is_Active, 0, GVL_Vars.G_Local_PLC_ID);

// 2. Инициализация и Бэкап (ТЗ 16.2)
L_Current_TOD := UDINT_TO_TOD(GVL_Vars.G_System_Time_MS MOD 86400000);
IF L_First_Cycle THEN
    L_First_Cycle := FALSE;
    fbNVRAM(VI_Command := 2, VI_RecordIndex := 1, VI_DataPtr := ADR(GVL_Vars.G_HMI_Gas_Config), VI_DataSize := SIZEOF(GVL_Vars.G_HMI_Gas_Config));
END_IF;

// Ежесуточный бэкап в 03:00 (ТЗ 16.2: Ротация 7 копий)
IF L_Current_TOD >= TOD#03:00 AND L_Current_TOD <= TOD#03:00:01 THEN
    fbNVRAM(VI_Command := 1, VI_RecordIndex := L_Backup_Day, VI_DataPtr := ADR(GVL_Vars.G_HMI_Gas_Config), VI_DataSize := SIZEOF(GVL_Vars.G_HMI_Gas_Config));
    L_Backup_Day := (L_Backup_Day MOD 7) + 1;
END_IF;

// 3. ТЗ 8.2: Параллельная обработка датчиков
FOR L_i := 1 TO 2 DO 
    L_Methane_LEL_Real[L_i] := GVL_IO.AI_Methane_LEL[L_i].rValue; 
END_FOR;
FOR L_i := 1 TO 5 DO 
    L_Manifold_Temps_Supply_Real[L_i] := GVL_IO.AI_Manifold_Temps_Supply[L_i].rValue; 
    L_Manifold_Temps_Return_Real[L_i] := TO_REAL(GVL_IO.AI_Manifold_Temps_Return[L_i]) / 10.0;
    L_Manifold_Pressures_Real[L_i] := TO_REAL(GVL_IO.AI_Manifold_Pressures[L_i]) / 100.0; // 0-10V -> 0-10.0 bar
    L_Manifold_Currents_Real[L_i] := TO_REAL(GVL_IO.AI_Manifold_Currents[L_i]) / 100.0; // 4-20mA -> 4.0-20.0 mA
END_FOR;

FOR L_i := 1 TO 15 DO
    // ПЛК A (ID=1) обрабатывает нечетные, ПЛК B (ID=2) - четные
    IF (GVL_Vars.G_Local_PLC_ID = 1 AND (L_i MOD 2 <> 0)) OR (GVL_Vars.G_Local_PLC_ID = 2 AND (L_i MOD 2 = 0)) THEN
        L_Opening_Sensors[L_i] := GVL_IO.DI_Security_Open[L_i];
        L_GlassBreak_Sensors[L_i] := GVL_IO.DI_Security_Glass[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO 12 DO
    IF (GVL_Vars.G_Local_PLC_ID = 1 AND (L_i MOD 2 <> 0)) OR (GVL_Vars.G_Local_PLC_ID = 2 AND (L_i MOD 2 = 0)) THEN
        L_Flood_Sensors[L_i] := GVL_IO.DI_Flood_Sensors[L_i];
    END_IF;
END_FOR;

    // 4. Сбор состояния
    L_System_State.Outdoor_Temp := GVL_IO.AI_Temp_Outdoor.rValue;
    FOR L_i := 1 TO 16 DO 
        L_System_State.Floor_Temps[L_i] := GVL_IO.AI_Floor_Temps[L_i]; 
        L_System_State.Indoor_Temp[L_i] := GVL_IO.AI_Room_Temps[L_i];
        L_System_State.CO2[MIN(L_i, 8)] := 400.0; 
        L_System_State.Humidity[MIN(L_i, 8)] := 45.0; 
    END_FOR;
    L_System_State.Security_Armed := GVL_Vars.G_Security_Armed;
    L_System_State.Flood_Alarm := GVL_Vars.G_Flood_Alarm_Active;
    L_System_State.Gas_Alarm := GVL_Vars.G_Gas_Alarm_Active;
    L_System_State.Fire_Alarm := GVL_Vars.G_Fire_Alarm_Active;

    // 5. Выполнение системной логики
    fbGasSmoke(
        VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
        VI_IsActivePLC := L_Is_Active,
        VI_Methane_LEL := L_Methane_LEL_Real,
        VI_CO_PPM := GVL_IO.AI_CO_PPM,
        VI_Smoke_Sensors := GVL_IO.DI_Smoke_Sensors,
        VI_Mute_Request := GVL_Vars.G_HMI_Mute_Alarm,
        VO_Gas_Alarm => GVL_Vars.G_Gas_Alarm_Active,
        VO_Fire_Alarm => GVL_Vars.G_Fire_Alarm_Active,
        VO_Gas_Valve_Close => GVL_IO.DO_Gas_Valve_Close
    );

    // ТЗ 3.6: При тревоге -> долгосрочный отъезд
    IF fbSecurity.VO_Long_Away_Req THEN
        GVL_Vars.G_Current_Scenario := E_SCENARIO_TYPE.SCENARIO_AWAY;
    END_IF;

    fbWater(
        VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
        VI_IsActivePLC := L_Is_Active,
        VI_Sensors := L_Flood_Sensors,
        VI_Valve_35_Current := GVL_IO.AI_Water_Valve_35_Current,
        VI_Valve_36_Current := GVL_IO.AI_Water_Valve_36_Current,
        VI_Config := GVL_Vars.G_Flood_Config,
        VI_Power_OK := GVL_IO.DI_Power_OK,
        VO_Flood_Alarm => GVL_Vars.G_Flood_Alarm_Active,
        VO_Valve_35_Close => GVL_IO.DO_Water_Valve_35_Close,
        VO_Valve_36_Close => GVL_IO.DO_Water_Valve_36_Close
    );

    fbHeating(
        VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
        VI_IsActivePLC := L_Is_Active AND NOT fbGasSmoke.VO_Boiler_Stop,
        VI_Outdoor_Temp := L_System_State.Outdoor_Temp,
        VI_Floor_Temps := GVL_IO.AI_Floor_Temps,
        VI_Room_Temps := GVL_IO.AI_Room_Temps,
        VI_Config := GVL_Vars.G_Heating_Config,
        VI_Manifold_Temps_Supply := L_Manifold_Temps_Supply_Real,
        VI_Manifold_Temps_Return := L_Manifold_Temps_Return_Real,
        VI_Manifold_Pressures := L_Manifold_Pressures_Real,
        VI_Manifold_Currents := L_Manifold_Currents_Real,
        VI_Boiler_Flame_Status := GVL_IO.AI_Boiler_Flame_Status,
        VI_Maintenance_Zones := GVL_Vars.G_Maintenance_Zones,
        VI_Maintenance_Manifolds := GVL_Vars.G_Maintenance_Manifolds,
        VO_Manifold_Pumps => GVL_IO.DO_Manifold_Pumps,
        VO_Zone_Valves => GVL_IO.DO_Zone_Valves,
        VO_Boiler_Enable => GVL_IO.DO_Boiler_Enable
    );
    // Конверсия выходов для Modbus
    FOR L_i := 1 TO 5 DO GVL_IO.AO_Manifold_Valves[L_i] := TO_UINT(fbHeating.VO_Manifold_Valves[L_i] * 10.0); END_FOR;
    FOR L_i := 1 TO 2 DO GVL_IO.AO_Boiler_Setpoint[L_i] := TO_UINT(fbHeating.VO_Boiler_Setpoint[L_i] * 10.0); END_FOR;

fbSecurity(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_IsActivePLC := L_Is_Active,
    VI_Opening_Sensors := L_Opening_Sensors,
    VI_GlassBreak_Sensors := L_GlassBreak_Sensors,
    VI_Config := GVL_Vars.G_Security_Config,
    VI_Group_2F_Open := GVL_IO.DI_Security_2F_Group, // ТЗ 3.1
    VI_Group_2F_Glass := GVL_IO.DI_Security_2F_Group, // ТЗ 3.2 (используем тот же канал если не выделен)
    VO_Armed => GVL_Vars.G_Security_Armed
);

fbAccessControl(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_IsActivePLC := L_Is_Active,
    VI_Armed := GVL_Vars.G_Security_Armed,
    VI_Gate_Open_Req := GVL_Vars.G_HMI_Gate_Open_Req,
    VI_Wicket_Open_Req := GVL_Vars.G_HMI_Wicket_Open_Req,
    VI_Lock_1_Open_Req := GVL_Vars.G_HMI_Lock_1_Open_Req,
    VI_Lock_1_Close_Req := GVL_Vars.G_HMI_Lock_1_Close_Req,
    VI_Lock_2_Open_Req := GVL_Vars.G_HMI_Lock_2_Open_Req,
    VI_Lock_2_Close_Req := GVL_Vars.G_HMI_Lock_2_Close_Req,
    VI_Config := GVL_Vars.G_Security_Config
);

// Сброс команд HMI (импульсные кнопки)
IF GVL_Vars.G_HMI_Gate_Open_Req AND NOT fbAccessControl.VO_Gate_Open THEN GVL_Vars.G_HMI_Gate_Open_Req := FALSE; END_IF;
IF GVL_Vars.G_HMI_Wicket_Open_Req AND NOT fbAccessControl.VO_Wicket_Open THEN GVL_Vars.G_HMI_Wicket_Open_Req := FALSE; END_IF;
IF GVL_Vars.G_HMI_Lock_1_Open_Req AND NOT fbAccessControl.VO_Lock_1_Open THEN GVL_Vars.G_HMI_Lock_1_Open_Req := FALSE; END_IF;
IF GVL_Vars.G_HMI_Lock_1_Close_Req AND NOT fbAccessControl.VO_Lock_1_Close THEN GVL_Vars.G_HMI_Lock_1_Close_Req := FALSE; END_IF;
IF GVL_Vars.G_HMI_Lock_2_Open_Req AND NOT fbAccessControl.VO_Lock_2_Open THEN GVL_Vars.G_HMI_Lock_2_Open_Req := FALSE; END_IF;
IF GVL_Vars.G_HMI_Lock_2_Close_Req AND NOT fbAccessControl.VO_Lock_2_Close THEN GVL_Vars.G_HMI_Lock_2_Close_Req := FALSE; END_IF;

// Маппинг на физические выходы
GVL_IO.DO_Gate_Open := fbAccessControl.VO_Gate_Open;
GVL_IO.DO_Wicket_Open := fbAccessControl.VO_Wicket_Open;
GVL_IO.DO_Lock_1_Open := fbAccessControl.VO_Lock_1_Open;
GVL_IO.DO_Lock_1_Close := fbAccessControl.VO_Lock_1_Close;
GVL_IO.DO_Lock_2_Open := fbAccessControl.VO_Lock_2_Open;
GVL_IO.DO_Lock_2_Close := fbAccessControl.VO_Lock_2_Close;

fbDHW(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_IsActivePLC := L_Is_Active,
    VI_Temp := GVL_IO.AI_DHW_Temp,
    VI_Pressure := GVL_IO.AI_DHW_Pressure,
    VI_Config := GVL_Vars.G_DHW_Config,
    VI_Maintenance := GVL_Vars.G_Maintenance_Lighting[1] // Условно используем ячейку для ГВС
);
GVL_IO.DO_DHW_Heating_Pump := fbDHW.VO_Heating_Pump;
GVL_IO.DO_DHW_Circ_Pump := fbDHW.VO_Circ_Pump;

fbVentilation(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_IsActivePLC := L_Is_Active,
    VI_CO2 := L_System_State.CO2,
    VI_Humidity := L_System_State.Humidity,
    VI_Gas_Alarm := GVL_Vars.G_Gas_Alarm_Active,
    VI_Fire_Alarm := GVL_Vars.G_Fire_Alarm_Active,
    VI_Flood_Alarm := GVL_Vars.G_Flood_Alarm_Active,
    VI_Config := GVL_Vars.G_Ventilation_Config,
    VI_PV3_Boost := fbGasSmoke.VO_Vent_PV3_Boost, // ТЗ 5.1
    VI_Supply_100_Req := fbGasSmoke.VO_Supply_100_Req, // ТЗ 6.4
    VI_Exhaust_100_Req := fbGasSmoke.VO_Exhaust_100_Req, // ТЗ 6.4
    VI_Supply_80_Req := fbGasSmoke.VO_Supply_80_Req, // ТЗ 5.4
    VI_Wet_Zone_Lights := fbLightingBlinds.VO_Wet_Zone_Light_Active // ТЗ 4.0
);
// Конверсия выходов вентиляции
FOR L_i := 1 TO 3 DO GVL_IO.AO_Supply_Fans[L_i] := TO_UINT(fbVentilation.VO_Supply_Fans[L_i] * 10.0); END_FOR;
FOR L_i := 1 TO 5 DO GVL_IO.AO_Exhaust_Fans[L_i] := TO_UINT(fbVentilation.VO_Exhaust_Fans[L_i] * 10.0); END_FOR;

fbSimulation(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_Enabled := (GVL_Vars.G_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY),
    VI_Intensity := 0.3
);

fbLightingBlinds(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_IsActivePLC := L_Is_Active,
    VI_Current_Scenario := GVL_Vars.G_Current_Scenario,
    VI_Away_Level := fbSecurity.VO_Away_Level,
    VI_Simulation_Active := (GVL_Vars.G_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY),
    VI_Simulation_Lights := fbSimulation.VO_Light_States,
    VI_Physical_Switches := GVL_IO.DI_Lighting_Switches, // ТЗ 1.0
    VI_Motion_Sensors := GVL_IO.DI_Motion_Sensors, // ТЗ 2.0
    VI_Maintenance := GVL_Vars.G_Maintenance_Lighting // ТЗ 6.0
);

fbRuleEngine(VI_System_State := L_System_State);

fbGateway(
    VI_System_Time_MS := GVL_Vars.G_System_Time_MS,
    VI_Local_PLC_Role := SEL(L_Is_Active, E_PLC_ROLE.ROLE_STANDBY, E_PLC_ROLE.ROLE_ACTIVE),
    VI_FloorHeating_Temps := GVL_IO.AI_Floor_Temps,
    VI_Room_Temps := GVL_IO.AI_Room_Temps,
    VI_Zone_Valve_States := GVL_IO.DO_Zone_Valves,
    VI_Manifold_Pressures := L_Manifold_Pressures_Real,
    VI_Manifold_Pump_States := GVL_IO.DO_Manifold_Pumps,
    VI_Outdoor_Temp := L_System_State.Outdoor_Temp,
    VI_Security_Armed := GVL_Vars.G_Security_Armed,
    VI_Flood_Alarm_Active := GVL_Vars.G_Flood_Alarm_Active,
    VI_Gas_Alarm_Active := GVL_Vars.G_Gas_Alarm_Active,
    VI_Fire_Alarm_Active := GVL_Vars.G_Fire_Alarm_Active,
    VI_Lighting_Base_Levels := fbLightingBlinds.VO_Lighting_Levels,
    VI_Blinds_Positions := fbLightingBlinds.VO_Blinds_Positions,
    VI_Active_Scenario := GVL_Vars.G_Current_Scenario
);

VO_Code_Valid := FALSE;

// Вычисляем хэш введенного кода
IF LEN(VI_Code_To_Check) > 0 THEN
    pCode := ADR(VI_Code_To_Check);
    L_Input_Hash := L_CRC_Calc.Calculate(VI_DataRef := pCode^, VI_Size := TO_UDINT(LEN(VI_Code_To_Check)));
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ACCESS_CODES DO
        IF VI_Access_Codes[L_i] <> 0 AND VI_Access_Codes[L_i] = L_Input_Hash THEN
            VO_Code_Valid := TRUE;
            RETURN;
        END_IF;
    END_FOR;
END_IF;

// Проверяем RFID метку
IF LEN(VI_RFID_To_Check) > 0 THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ACCESS_CODES DO
        IF VI_RFID_Tags[L_i] <> '' AND VI_RFID_Tags[L_i] = VI_RFID_To_Check THEN
            VO_Code_Valid := TRUE;
            RETURN;
        END_IF;
    END_FOR;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_AccessCode_Manager <<<

IF NOT L_Initialized THEN
    L_Write_Index := GVL_Retain.G_BlackBox_LastIndex;
    IF L_Write_Index < 0 OR L_Write_Index >= GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS THEN
        L_Write_Index := 0;
        GVL_Retain.G_BlackBox_LastIndex := 0;
    END_IF;
    L_Initialized := TRUE;
END_IF;

IF VI_Freeze THEN
    GVL_Retain.G_BlackBox_Frozen := TRUE;
END_IF;

VO_Frozen := GVL_Retain.G_BlackBox_Frozen;

IF NOT GVL_Retain.G_BlackBox_Frozen THEN
    GVL_Retain.G_BlackBox_Buffer[L_Write_Index] := VI_Current_Data;
    GVL_Retain.G_BlackBox_LastIndex := L_Write_Index;

    L_Write_Index := L_Write_Index + 1;
    IF L_Write_Index >= GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS THEN
        L_Write_Index := 0;
    END_IF;
END_IF;

VO_Records_Count := GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS; // Размер кольцевого буфера
// >>> BULK_SYNC_ANCHOR: FB_BlackBox_Recorder <<<

IF L_Initialized THEN RETURN; END_IF;

FOR L_i := 0 TO 255 DO
    L_Entry := TO_DWORD(L_i);
    FOR L_j := 0 TO 7 DO
        IF (L_Entry AND 1) <> 0 THEN
            L_Entry := SHR(L_Entry, 1) XOR 16#EDB88320;
        ELSE
            L_Entry := SHR(L_Entry, 1);
        END_IF;
    END_FOR;
    L_Table[L_i] := L_Entry;
END_FOR;
L_Initialized := TRUE;

// Цикл логирования
IF VI_Config.enabled AND (VI_System_Time_MS - L_last_log_time >= VI_Config.sampling_period_ms) THEN
    L_last_log_time := VI_System_Time_MS;

    // Логируем температуры (если изменились или по таймауту)
    FOR L_i := 1 TO 16 DO
        L_buffer[L_write_idx].timestamp_ms := VI_System_Time_MS;
        L_buffer[L_write_idx].level := E_Debug_Log_Level.LOG_LEVEL_VERBOSE;
        L_buffer[L_write_idx].source_id := TO_BYTE(L_i);
        L_buffer[L_write_idx].value_real := VI_Floor_Temps[L_i];
        L_buffer[L_write_idx].text := 'Floor Temp Update';

        L_write_idx := (L_write_idx MOD 1000) + 1;
    END_FOR;

    // Логируем ошибки
    IF VI_Error_Code <> 0 THEN
        L_buffer[L_write_idx].timestamp_ms := VI_System_Time_MS;
        L_buffer[L_write_idx].level := E_Debug_Log_Level.LOG_LEVEL_MINIMAL;
        L_buffer[L_write_idx].event_code := TO_WORD(VI_Error_Code);
        L_buffer[L_write_idx].text := 'System Error Detected';
        L_write_idx := (L_write_idx MOD 1000) + 1;
    END_IF;
END_IF;

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

L_DHW_V2_Shadow_Diff_Found := FALSE;
L_DHW_V2_Switch_Enabled := TRUE;
L_DHW_V2_Path_Ready := FALSE;
L_DHW_Using_Legacy_Fallback := TRUE;

GVL_STATE.G_DHW_IO_Fault := FALSE;
GVL_STATE.G_DHW_Sensor_Fault := FALSE;
GVL_STATE.G_DHW_Subsystem_Degraded := FALSE;

IF VI_Emergency_Stop THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    VO_Status.Warning := FALSE;
    VO_Status.Error := TRUE;
    VO_Status.Error_ID := GVL_CONFIG.ERR_DHW_IO_OFFLINE; // временно используем общий аварийный код до детализации safety-кодов
    VO_Status.Heating_Pump_On := FALSE;
    VO_Status.Circ_Pump_On := FALSE;
    RETURN;
END_IF;

// Фиксация текущего времени
L_Current_TOD := VI_Current_TOD;

// ========================================
// DHW POLICY LAYER
// ========================================
L_Policy_Safe_Stop := (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
L_Policy_Freeze_Protection := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);
L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
L_Target_Temp_Adjusted := VI_Config.Target_Temp;
IF L_Policy_Degraded THEN
    L_Target_Temp_Adjusted := VI_Config.Target_Temp - VI_Config.Degraded_Target_Delta;
END_IF;

// ========================================
// DHW POLICY OVERRIDE
// ========================================
IF L_Policy_Safe_Stop THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    RETURN;
END_IF;

IF L_Policy_Freeze_Protection THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    RETURN;
END_IF;

// Сброс признака выполнения термодезинфекции при смене дня.
IF L_Last_Legionella_Day <> VI_Current_Day_Of_Week THEN
    L_Legionella_Done_Today := FALSE;
    L_Last_Legionella_Day := VI_Current_Day_Of_Week;
END_IF;

// Базовый сброс незащёлкнутых статусных флагов на текущий цикл.
// Критические ошибки ниже могут зафиксироваться и завершить выполнение через RETURN.
VO_Status.Warning := FALSE;
VO_Status.Error := FALSE;
VO_Status.Error_ID := 0;

// Сброс ошибок
IF VI_Reset_Errors THEN
    L_Error_Latched := FALSE;
    L_Error_ID_Latched := 0;
END_IF;

// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        L_Error_Latched := TRUE;
        GVL_STATE.G_DHW_IO_Fault := TRUE;
        L_Error_ID_Latched := GVL_CONFIG.ERR_DHW_IO_OFFLINE; // Потеря связи с модулями ввода-вывода
    END_IF;
END_FOR;

// 1. Обработка неисправностей датчиков и сервисных режимов (ТЗ 7.0)
fbTempValidator(
    VI_Value := VI_Temp,
    VI_Min_Valid := 0.0,
    VI_Max_Valid := 100.0,
    VI_Fallback_Mode := 0,
    VI_Default_Value := 55.0
);

fbPressValidator(
    VI_Value := VI_Pressure,
    VI_Min_Valid := 0.0,
    VI_Max_Valid := 10.0,
    VI_Fallback_Mode := 0
);

VO_Status.Temp := fbTempValidator.VO_Value;
VO_Status.Pressure := fbPressValidator.VO_Value;

// Сохраняем последнее достоверное значение температуры ГВС.
// Используется только для диагностики/сервиса, не для fallback-управления.
IF NOT fbTempValidator.VO_Error THEN
    L_Last_Good_Temp := VO_Status.Temp;
END_IF;

IF fbTempValidator.VO_Error THEN
    GVL_STATE.G_DHW_Sensor_Fault := TRUE;
    L_Error_Latched := TRUE;
    L_Error_ID_Latched := GVL_CONFIG.ERR_DHW_TEMP_SENSOR_FAULT; // Критическая ошибка датчика температуры
ELSIF (VO_Status.Pressure < 1.0 OR VO_Status.Pressure > 4.0) AND NOT fbPressValidator.VO_Error THEN
    L_Error_Latched := TRUE;
    L_Error_ID_Latched := GVL_CONFIG.ERR_DHW_PRESSURE_OUT_OF_RANGE; // Давление вне нормы
END_IF;

IF L_Error_Latched THEN
    // Критическая ошибка: переход в безопасное состояние с полной остановкой насосов.
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    VO_Status.Warning := FALSE;
    VO_Status.Error := TRUE;
    VO_Status.Error_ID := L_Error_ID_Latched;
    VO_Status.Heating_Pump_On := FALSE;
    VO_Status.Circ_Pump_On := FALSE;
    RETURN;
END_IF;

// Ошибка датчика давления не останавливает ГВС,
// но переводит подсистему в режим предупреждения (degraded mode).
IF fbPressValidator.VO_Error THEN
    GVL_STATE.G_DHW_Sensor_Fault := TRUE;
    GVL_STATE.G_DHW_Subsystem_Degraded := TRUE;
    VO_Status.Warning := TRUE;
    VO_Status.Error := FALSE;
    VO_Status.Error_ID := GVL_CONFIG.ERR_DHW_PRESSURE_SENSOR_FAULT;
END_IF;

// 2. Логика поддержания температуры воды в бойлере (Нагрев)
// На этом этапе FB уже выполняется только на активном ПЛК.

// Термическая дезинфекция (Легионелла)
IF VI_Config.Anti_Legionella_Enabled
   AND (VI_Current_Day_Of_Week = VI_Config.Anti_Legionella_Day)
   AND (L_Current_TOD >= TOD#02:00)
   AND (L_Current_TOD <= TOD#04:00)
   AND NOT L_Legionella_Done_Today THEN
    L_Legionella_Active := TRUE;
ELSE
    L_Legionella_Active := FALSE;
END_IF;

L_Legionella_Timer(IN := L_Legionella_Active AND VO_Status.Temp >= 70.0, PT := T#30m, VI_System_Time_MS := VI_System_Time_MS);
IF L_Legionella_Timer.Q THEN
    L_Legionella_Active := FALSE; // Дезинфекция завершена
    L_Legionella_Done_Today := TRUE; // Повторно в те же сутки не запускать
END_IF;

// Двухпозиционное регулирование с гистерезисом
IF L_Legionella_Active THEN
    IF VO_Status.Temp < 70.0 THEN
        VO_Heating_Pump := TRUE;
    ELSIF VO_Status.Temp > 72.0 THEN
        VO_Heating_Pump := FALSE;
    END_IF;
ELSE
    IF VO_Status.Temp < (L_Target_Temp_Adjusted - VI_Config.Hysteresis) THEN
        VO_Heating_Pump := TRUE;
    ELSIF VO_Status.Temp > (L_Target_Temp_Adjusted + VI_Config.Hysteresis) THEN
        VO_Heating_Pump := FALSE;
    END_IF;
END_IF;

// 3. Управление циркуляционным насосом ГВС по расписанию
// Рециркуляция обеспечивает мгновенное наличие горячей воды у потребителя
VO_Circ_Pump := VI_Config.Circulation_Schedule_Enabled AND NOT (VI_Config.Night_Mode_Enabled AND (L_Current_TOD < VI_Config.Circulation_Start OR L_Current_TOD > VI_Config.Circulation_End));

// Формирование статусных данных для визуализации.
// К этому моменту статус уже консистентен:
// - Error = критическая ошибка с остановкой ГВС
// - Warning = деградация без остановки
VO_Status.Heating_Pump_On := VO_Heating_Pump;
VO_Status.Circ_Pump_On := VO_Circ_Pump;

// ========================================
// DHW V2 shadow execution (phase2)
// ========================================
fbDHWV2Staging(
    VI_Tank_ID := 1,
    VI_Enable := TRUE,
    VI_Target_Temp := VI_Config.Target_Temp,
    VI_Pump_Enable := VO_Heating_Pump,
    VI_Heating_Priority := FALSE,

    VI_Is_Active := TRUE,
    VI_Tank_Temp := VO_Status.Temp,
    VI_Supply_Temp := VO_Status.Temp,
    VI_Return_Temp := VO_Status.Temp,
    VI_Pump_Actual := VO_Heating_Pump,
    VI_Alarm_Active := VO_Status.Error,

    VO_Command_Shadow => L_DHW_V2_Command_Shadow,
    VO_State_Shadow => L_DHW_V2_State_Shadow
);

// ========================================
// DHW V2 shadow validation
// ========================================
IF ABS(VO_Heating_Pump - L_DHW_V2_Command_Shadow.Pump_Enable) > 0.1 THEN
    L_DHW_V2_Shadow_Diff_Found := TRUE;
END_IF;
IF ABS(VO_Status.Temp - L_DHW_V2_State_Shadow.Tank_Temp) > 0.1 THEN
    L_DHW_V2_Shadow_Diff_Found := TRUE;
END_IF;
IF ABS(VO_Status.Pressure - L_DHW_V2_State_Shadow.Supply_Temp) > 0.1 THEN
    L_DHW_V2_Shadow_Diff_Found := TRUE;
END_IF;

// Guarded DHW V2 enable
IF L_DHW_V2_Switch_Enabled THEN
    IF NOT L_DHW_V2_Shadow_Diff_Found THEN
        L_DHW_V2_Path_Ready := TRUE;
        L_DHW_Using_Legacy_Fallback := FALSE;
    ELSE
        L_DHW_V2_Path_Ready := FALSE;
        L_DHW_Using_Legacy_Fallback := TRUE;
    END_IF;
ELSE
    L_DHW_V2_Path_Ready := FALSE;
    L_DHW_Using_Legacy_Fallback := TRUE;
END_IF;

END_FUNCTION_BLOCK
// >>> BULK_SYNC_ANCHOR: FB_DHW_Manager <<<

IF VI_Humidity > VI_Config.Threshold_Hum THEN
    VO_Fan_Speed := 100;
ELSIF VI_CO2 > 800.0 THEN
    VO_Fan_Speed := 70;
ELSE
    VO_Fan_Speed := 40;
END_IF;

VO_Flood_Alarm := FALSE;
VO_Close_Valve_35 := FALSE;
VO_Close_Valve_36 := FALSE;

FOR L_i := 1 TO 12 DO
    IF VI_Sensors[L_i] THEN
        VO_Flood_Alarm := TRUE;
        IF VI_IsActivePLC THEN
            // Логика п. 4.2: Зона 2 (4-5) и Зона 3 (6-7) делят клапан 36
            IF L_i >= 4 AND L_i <= 7 THEN
                VO_Close_Valve_36 := TRUE;
            ELSIF L_i >= 1 AND L_i <= 3 THEN
                VO_Close_Valve_35 := TRUE;
            END_IF;
        END_IF;
    END_IF;
END_FOR;

VO_Freeze_Alert := FALSE;
VO_Pump_Force_On := FALSE;

FOR L_i := 1 TO 16 DO
    IF VI_Floor_Temps[L_i] < VI_Threshold THEN
        VO_Freeze_Alert := TRUE;
        VO_Pump_Force_On := TRUE;
        RETURN;
    END_IF;
END_FOR;

IF VI_Outdoor_Temp < -5.0 THEN
    VO_Pump_Force_On := TRUE;
END_IF;

VO_Overheat_Detected := FALSE;
FOR L_i := 1 TO 16 DO
    IF VI_Temps[L_i] > VI_Threshold THEN
        VO_Overheat_Detected := TRUE;
        VO_Locked_Circuits[L_i] := TRUE;
    END_IF;
END_FOR;

// При аварии газа - немедленное закрытие
IF VI_Gas_Alarm AND VI_IsActivePLC THEN
    VO_Valve_Closed := TRUE;
    VO_Status_Msg := 'ГАЗОВЫЙ КЛАПАН ЗАКРЫТ ПО АВАРИИ';
END_IF;

IF VI_Write_Event AND NOT L_Prev_Write_Event THEN
    GVL_Retain.G_History_Buffer[GVL_Retain.G_History_Write_Idx] := VI_Event;
    GVL_Retain.G_History_Buffer[GVL_Retain.G_History_Write_Idx].timestamp_ms := VI_System_Time_MS;

    GVL_Retain.G_History_Write_Idx := (GVL_Retain.G_History_Write_Idx MOD GVL_CONSTANTS.C_MAX_HISTORY_RECORDS) + 1;
    GVL_Retain.G_History_Total_Events := GVL_Retain.G_History_Total_Events + 1;
END_IF;
L_Prev_Write_Event := VI_Write_Event;

VO_Total_Events := GVL_Retain.G_History_Total_Events;
// >>> BULK_SYNC_ANCHOR: FB_History_Manager <<<

// Упрощенная модель износа
IF VI_Nominal_Life > 0 THEN
    VO_Remaining_Percent := TO_BYTE(100 - (VI_Runtime_Hours * 100 / VI_Nominal_Life));
ELSE
    VO_Remaining_Percent := 0;
END_IF;

VO_Maintenance_Req := (VO_Remaining_Percent < 10);

IF VI_Enable_Request THEN
    VO_Speed_Percent := 100;
    VO_Running := TRUE;
    L_Stopping := FALSE;
ELSE
    IF VO_Running AND NOT L_Stopping THEN
        L_Stopping := TRUE;
        L_Stop_Start_Time := VI_System_Time;
    END_IF;

    IF L_Stopping THEN
        L_elapsed := VI_System_Time - L_Stop_Start_Time;
        IF L_elapsed < VI_Stop_Ramp_MS THEN
            // Исправлено: защита от отрицательного значения
            VO_Speed_Percent := REAL_TO_BYTE(100.0 * (1.0 - TO_REAL(L_elapsed) / TO_REAL(VI_Stop_Ramp_MS)));
        ELSE
            VO_Speed_Percent := 0;
            VO_Running := FALSE;
            L_Stopping := FALSE;
        END_IF;
    END_IF;
END_IF;

// Запуск за 3 часа (10800000 мс)
IF (VI_Departure_Time - VI_System_Time) < 10800000 THEN
    VO_Heating_Active := TRUE;
    FOR L_i := 1 TO 16 DO
        IF VI_Selected[L_i] THEN VO_Setpoints[L_i] := 22.0; END_IF;
    END_FOR;
ELSE
    VO_Heating_Active := FALSE;
END_IF;

L_seed := (C_LCG_MULTIPLIER * L_seed) + C_LCG_INCREMENT;

IF VI_max > VI_min THEN
        L_range := VI_max - VI_min;
        // Используем LREAL для точности и исключения выхода за границу
        L_rand_factor := TO_LREAL(L_seed) / C_LCG_MODULUS;
        Random_Int_Range := VI_min + TO_UDINT(L_rand_factor * TO_LREAL(L_range + 1));

        // Финальная защита от переполнения
        IF Random_Int_Range > VI_max THEN
            Random_Int_Range := VI_max;
        END_IF;
    ELSE
        Random_Int_Range := VI_min;
    END_IF;

IF NOT VI_IsActivePLC THEN
    RETURN;
END_IF;

CASE VI_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP,
    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        IF VO_Current_Scenario <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
            VO_Current_Scenario := E_SCENARIO_TYPE.SCENARIO_NONE;
            VO_Status_Msg := 'Сценарии принудительно отключены режимом безопасности';
        END_IF;
        RETURN;

    E_System_Operating_Mode.MODE_DEGRADED:
        VO_Status_Msg := 'Смена сценариев заблокирована: деградированный режим';
        RETURN;
END_CASE;

IF VI_Activate_Request <> VO_Current_Scenario THEN
    // Проверка минимального времени работы сценария
    IF F_TimeDiff(VI_System_Time_MS, L_Last_Scenario_Time) >= 60000 OR VO_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_NONE THEN
        // Логика переключения сценариев
        VO_Current_Scenario := VI_Activate_Request;
        L_Last_Scenario_Time := VI_System_Time_MS;

        CASE VO_Current_Scenario OF
        E_SCENARIO_TYPE.SCENARIO_NONE:
            VO_Status_Msg := 'Сценарии отключены';
        E_SCENARIO_TYPE.SCENARIO_AWAY:
            VO_Status_Msg := 'Активирован сценарий: Вне дома (Охрана + Энергосбережение)';
        E_SCENARIO_TYPE.SCENARIO_SLEEP:
            VO_Status_Msg := 'Активирован сценарий: Сон (Ночное освещение + Климат)';
        E_SCENARIO_TYPE.SCENARIO_PRESENCE:
            VO_Status_Msg := 'Активирован сценарий: Имитация присутствия';
        END_CASE;
    END_IF;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Scenario_Manager <<<

VO_Alarm_Active := CheckPerimeter();

IF VO_Alarm_Active THEN
    VO_Status_Msg := 'ТРЕВОГА: НАРУШЕН ПЕРИМЕТР';
ELSE
    VO_Status_Msg := 'Периметр в норме';
END_IF;

FOR L_i := 1 TO 6 DO
    IF VI_Sensors[L_i] THEN
        IF NOT L_Verifying[L_i] THEN
            L_Verifying[L_i] := TRUE;
            L_Verify_Start[L_i] := VI_System_Time;
        ELSIF (VI_System_Time - L_Verify_Start[L_i]) > 30000 THEN
            VO_Fire_Alarm := TRUE;
        END_IF;
    ELSE
        L_Verifying[L_i] := FALSE;
    END_IF;
END_FOR;

CASE L_State OF
    0: // Ожидание запроса
        IF VI_Send_Request THEN
            VO_Done := FALSE;
            VO_Error := FALSE;
            L_State := 1;
        END_IF;

    1: // Отправка AT+CMGF=1 (Установка текстового режима)
        L_AT_Command := 'AT+CMGF=1$R';
        L_State := 2;
        L_Timer(IN := TRUE, PT := T#500ms);

    2: // Ожидание ответа OK и отправка номера
        L_Timer(IN := TRUE);
        IF L_Timer.Q THEN
            L_Timer(IN := FALSE);
            L_AT_Command := CONCAT('AT+CMGS="', CONCAT(VI_Phone, '"$R'));
            L_State := 3;
            L_Timer(IN := TRUE, PT := T#500ms);
        END_IF;

    3: // Отправка текста сообщения и символа Ctrl+Z (ASCII 26)
        L_Timer(IN := TRUE);
        IF L_Timer.Q THEN
            L_Timer(IN := FALSE);
            L_AT_Command := CONCAT(VI_Text, '$1A'); // $1A - это Ctrl+Z в CODESYS
            L_State := 4;
            L_Timer(IN := TRUE, PT := T#2s);
        END_IF;

    4: // Завершение
        L_Timer(IN := TRUE);
        IF L_Timer.Q THEN
            L_Timer(IN := FALSE);
            VO_Done := TRUE;
            L_State := 0;
        END_IF;
END_CASE;

IF VI_Save_Req THEN
    L_Buffer[L_Idx] := VI_Snapshot;
    L_Buffer[L_Idx].timestamp_ms := VI_System_Time;
    VO_Last_ID := VI_System_Time;
    L_Idx := (L_Idx + 1) MOD 10;
END_IF;

IF VI_Op = 'ADMIN' THEN
    // Если 2FA включена, проверяем флаг прохождения второго фактора
    IF GVL_HMI_Config.G_HMI_Admin_2FA_Enabled THEN
        CheckAccess := GVL_HMI_Config.G_HMI_Current_Operator_Factor2_Done;
    ELSE
        CheckAccess := TRUE;
    END_IF;
ELSIF VI_Op = 'SERVICE' AND VI_Req_Level <= 3 THEN
    CheckAccess := TRUE;
ELSE
    CheckAccess := FALSE;
END_IF;
